questoes.solucao_referencia:
#include <stdio.h>

int main(void) {
    int a, b;
    scanf("%d %d", &a, &b);
    printf("%d\n", a + b);
    return 0;
}

#include <stdio.h>

int main(void) {
    double x;
    scanf("%lf", &x);
    printf("%.2f\n", 2.0 * x);
    return 0;
}

#include <stdio.h>

int main(void) {
    int a, b, c;
    scanf("%d %d %d", &a, &b, &c);
    printf("%.2f\n", (a + b + c) / 3.0);
    return 0;
}

#include <stdio.h>

int main(void) {
    double c;
    scanf("%lf", &c);
    printf("%.2f\n", 9.0 / 5.0 * c + 32.0);
    return 0;
}

#include <stdio.h>

int main(void) {
    int a, b;
    scanf("%d %d", &a, &b);
    printf("%d %d\n", a / b, a % b);
    return 0;
}

#include <stdio.h>

int main(void) {
    int lado;
    scanf("%d", &lado);
    printf("%d\n", 4 * lado);
    printf("%d\n", lado * lado);
    return 0;
}

#include <stdio.h>

int main(void) {
    int h, m, s;
    scanf("%d %d %d", &h, &m, &s);
    printf("%d\n", h * 3600 + m * 60 + s);
    return 0;
}

#include <stdio.h>

int main(void) {
    double preco;
    int qtd;
    scanf("%lf %d", &preco, &qtd);
    printf("%.2f\n", preco * qtd);
    return 0;
}
